/// <summary>
/// NS Zelinka 19.03.24
/// </summary>
[ExtensionOf(formStr(AVAPTMToolTable))]
final class AVAPTMToolTableFrm_Extension
{
    public boolean frmCallMethodsAfterCreation;

}

Method.Source:
/// <summary>
/// NS Zelinka 19.03.24
/// </summary>
public void init()
{
    FormStringControl   formStringControlICProjProd;
    FormStringControl   formStringControlICProjMaintenance;

    next init();

    frmCallMethodsAfterCreation         = true;

    formStringControlICProjProd         = this.design().controlName(formControlStr(AVAPTMToolTable, AVAICProjProd_AVAICProjProd));
    formStringControlICProjProd.registerOverrideMethod( methodStr(FormStringControl, jumpRef),
                                                        methodStr(AVAPTMToolTableFrm_Extension, AVAICProjProdJumpRef));

    formStringControlICProjMaintenance  = this.design().controlName(formControlStr(AVAPTMToolTable, AVAICProjMaintenance_AVAICProjMaintenance));
    formStringControlICProjMaintenance.registerOverrideMethod(  methodStr(FormStringControl, jumpRef),
                                                                methodStr(AVAPTMToolTableFrm_Extension, AVAICProjMaintenanceJumpRef));
}

/// <summary>
/// NS Zelinka 19.03.24
/// </summary>
/// <param name = "_formControl">FormControl</param>
public void AVAICProjProdJumpRef(FormControl _formControl)
{
    KCS_PTMToolTable    toolTable = _formControl.formRun().dataSource(formDataSourceStr(AVAPTMToolTable, PTMToolTable)).cursor();

    if (toolTable.KCS_ProducerUK == ''  ||
        toolTable.KCS_ProducerUK == curExt())
    {
        this.AVAOpenProjTable(toolTable.AVAICProjProd);
    }
    else
    {
        changecompany(toolTable.KCS_ProducerUK)
        {
            this.AVAOpenProjTable(toolTable.AVAICProjProd);
        }
    }
}

/// <summary>
/// NS Zelinka 19.03.24
/// </summary>
/// <param name = "_formControl">FormControl</param>
public void AVAICProjMaintenanceJumpRef(FormControl _formControl)
{
    KCS_PTMToolTable    toolTable = _formControl.formRun().dataSource(formDataSourceStr(AVAPTMToolTable, PTMToolTable)).cursor();

    if (toolTable.KCS_MaintenanceUK == ''  ||
        toolTable.KCS_MaintenanceUK == curExt())
    {
        this.AVAOpenProjTable(toolTable.AVAICProjMaintenance);
    }
    else
    {
        changecompany(toolTable.KCS_MaintenanceUK)
        {
            this.AVAOpenProjTable(toolTable.AVAICProjMaintenance);
        }
    }
}

/// <summary>
/// NS Zelinka 19.03.24
/// </summary>
/// <param name = "_projId">ProjId</param>
public void AVAOpenProjTable(ProjId _projId)
{
    Args            locArgs;
    MenuFunction    locMenuFunction;
    ProjTable       locProjTable;

    locProjTable = ProjTable::find(_projId);
    if(locProjTable.RecId)
    {
        locArgs         = new Args();
        locArgs.record(locProjTable);
        locMenuFunction = new MenuFunction(menuitemDisplayStr(ProjTable),MenuItemType::Display);
        if (    locMenuFunction
            &&  locMenuFunction.checkAccessRights() )
        {
            locMenuFunction.run(locArgs);
        }
    }
}

/// <summary>
///     AVA <c>close</c> method.
///     AVA - Schneider 15.08.2024
/// </summary>
public void close()
{
    Args                locArgs;

    FormRun             locFormRunCaller;
    KCS_PTMToolTable    locKCS_PTMToolTable;

    locArgs             = this.args();
    locFormRunCaller    = locArgs.caller();
    //locKCS_PTMToolTable =  this.for .formRun().dataSource(formDataSourceStr(AVAPTMToolTable, PTMToolTable)).cursor();
    locKCS_PTMToolTable =  PTMToolTable_DS.cursor();

    if (    frmCallMethodsAfterCreation 
        &&  formHasMethod(locFormRunCaller, literalStr(avaAfterKCS_PTMToolTableCreation)))
    {
        locFormRunCaller.avaAfterKCS_PTMToolTableCreation(locKCS_PTMToolTable);
    }

    next close();
}

/// <summary>
///     AVA <c>closeCancel</c> method.
///     AVA - Schneider 15.08.2024
/// </summary>
public void closeCancel()
{
    next closeCancel();

    frmCallMethodsAfterCreation = false;
}

/// <summary>
///     AVA <c>closeOk</c> method.
///     AVA - Schneider 15.08.2024
/// </summary>
public void closeOk()
{
    next closeOk();

    frmCallMethodsAfterCreation = true;
}
